UPDATE biz_spas_reservation_stock
SET reserved_count = reserved_count + 1,
    sold_out_time  = CASE
                        WHEN reserved_count + 1 >= reservation_count THEN NOW()
                        ELSE sold_out_time
                    END,
    update_time = #{updateTime}
WHERE project_id = #{projectId}
  AND reservation_time = #{reservationTime}
